async () => {
window.__ev=[]; for (const n of ['phone_call_answered:caller_decline','phone_call_declined:caller_decline','phone_call_missed:caller_decline','phone_call_declined:caller_patient','phone_call_declined:caller_voicemail','phone_call_declined:caller_terminal','phone_call_missed:caller_debrief','phone_call_answered:caller_debrief','conversation_closed:caller_debrief']) window.eventDispatcher.on(n, d => window.__ev.push([n, d && d.callback === true ? 'callback' : ''])); window.__toasts=[]; const sn=window.showNotification; window.showNotification=function(t){ window.__toasts.push(String(t)); return sn.apply(this, arguments); }; return true;

}

