async () => {
const out={}; for (const id of ['caller_patient','caller_decline','caller_voicemail','caller_terminal','caller_debrief','caller_thread','desk_contact']) { const o=window.npcManager.getNPC(id); const h=window.npcManager.getConversationHistory(id)||[]; out[id]={rows:h.filter(m=>m.type==='call').map(m=>m.text+(m.read?'':' [unread]')), lines:h.filter(m=>m.type!=='call').map(m=>m.text), callback:window.phoneRinger.callbackFor(id), slot:o&&o.pendingCall?JSON.parse(JSON.stringify(o.pendingCall)):null, currentKnot:o&&o.currentKnot}; } const m=window.MinigameFramework.currentMinigame; out._open=m?{type:m._sceneType,npc:m.params&&m.params.npcId||null}:null; return out;

}

async () => {
return {events: window.__ev, toasts: window.__toasts};

}

