async () => {
const m=document.querySelector('.messages-container'); const hb=document.querySelector('.call-button'); const rb=[...document.querySelectorAll('.call-row-callback')].map(b=>b.getAttribute('aria-label')); return {header: hb?{text:hb.innerText.trim(),aria:hb.getAttribute('aria-label')}:null, rowButtons:rb, text:m?m.innerText.replace(/\n+/g,' | '):null, choices:[...document.querySelectorAll('.choice-button')].map(b=>b.innerText.trim())};

}

